/*
******************************************************************
	Macro Title: Close All Open Doors
	Author: TheJoester (https://github.com/thejoester)
	Description:
	Closes only currently open or locked doors (ds !== CLOSED)
	in the current scene.
	Foundry Version: 12
	Last updated: 4-Apr-2025
******************************************************************
*/

const updateDoors = async (updates) => {
	// Filter for door walls that are NOT already closed
	const doors = canvas.scene.walls.filter(w => w.door > 0 && w.ds !== CONST.WALL_DOOR_STATES.CLOSED);

	if (doors.length === 0) {
		return ui.notifications.info("All doors are already closed.");
	}

	const changes = doors.map(w => ({ _id: w.id, ...updates }));
	await canvas.scene.updateEmbeddedDocuments("Wall", changes);
	ui.notifications.info(`Closed ${changes.length} door(s).`);
};

// Close all doors that aren't already closed
updateDoors({ ds: CONST.WALL_DOOR_STATES.CLOSED });
